facilityFormItem.itemAddedEventHandler:
        const table = functions.getValues().PlannedVacationGrid;
        const index = table.length -1;
        const  defaultDate = functions.getValues().Year + '-01-01T00:00:00';
        const { rowIndex } = table[index];
        functions.setValue('PlannedVacationGrid', defaultDate, rowIndex, 'BeginDate');

        // Подставляем первый из оплачиваемых, если такой есть.
        // Если такого нет - первый из неоплачиваемых.
        const availableVacations = JSON.parse(functions.getValues().AvailableDaysJson);
        const paidVacation = availableVacations.find(vacation => vacation.IsPaid === true);
        const unpaidVacation = availableVacations.find(vacation => vacation.IsPaid === false);
        const vacationKindId = paidVacation ? paidVacation.Id : (unpaidVacation ? unpaidVacation.Id : 0);
        functions.setValue('PlannedVacationGrid', vacationKindId, rowIndex, 'AvailableVacationId');

