                  .then(function (warning) {
                    if(warning.length > 0)
                      ESS.toasts.showToast(warning, ESS.enums.ToastType.WARNING, true);
                  })
                  .catch(function(error) {
                    ESS.toasts.showToast(error.message, 'danger', false);
                  });
                });
              })
              .catch(function(error) {
                ESS.toasts.showToast(error.message, 'danger', false);
              });
            }

facilityFormItem.onClickEventHandler:
        const dialogId = 'scheduleVacationPlanningTool';
        const callDialog = () => {
          if (!Object.keys(context.canShowDialog).length) {
            const timeline = {
              type: ESS.enums.DialogItemType.TEXT,
              name: 'timeline',
              properties: {
                text: `
                  <component
                    name="VacationPlanningTool"
                    public-name="Directum_VacationPlanningTool_1_0"
                    module-name="loaders"
                    loader-name="lk-loader"
                    dialog-id="${dialogId}"
                  />
                `,
              },
            };
            const id = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'AssignmentId',
              properties: {
                initialValue: functions.getValues().AssignmentId,
                isHidden: true,
              },
            };

            const performerId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'PerformerId',
              properties: {
                initialValue: functions.getValues().PerformerId,
                isHidden: true,
              },
            };

            const vacations = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'Vacations',
              properties: {
                initialValue: JSON.stringify(functions.getValues().PlannedVacationGrid),
                isHidden: true,
              },
            };

            const entityGuid = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EntityGuid',
              properties: {
                initialValue: 'f178357e-6bfe-42d7-8a55-7013389de185',
                isHidden: true,
              },
            };

            const items = [
              timeline,
              id,
              vacations,
              performerId,
              entityGuid
            ];

            ESS.dialogs.createDialog({
              id: dialogId,
              properties: {
                width: ESS.enums.DialogWidth.WIDE,
                isFullScreen: true,
              },
              title: `${ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_DIALOG_TITLE')} ${functions.getValues().Year}`,
              items,
            });
            clearInterval(intervalId);
          }
        }

        let intervalId = setInterval(callDialog, 300);

facility.openingEventHandler:
    context.canShowDialog = {};
    context.sendRequest = (...args) => {
      const key = Date.now();
      context.canShowDialog[key] = '';
      return ESS.network.sendRequest(...args).finally(() => delete context.canShowDialog[key]);
    };
    window.refreshAvailableDays = () =>
    {
      var availableDays = JSON.parse(functions.getValues()['AvailableDaysJson']);
      var vacationTable = functions.getValues().PlannedVacationGrid;
      var count = 0;
      var vacations = availableDays.map(function (vacationData) {
        count = vacationData.Count;
        var mandatoryCount = vacationData.MandatoryDays;
        vacationTable.forEach(function (row) {
          if (row.rowValues.AvailableVacationId == vacationData.Id) {
            count = count - row.rowValues.VacationDuration;
            mandatoryCount = mandatoryCount - row.rowValues.VacationDuration;
          }
        });
        var objForIE = {};
        objForIE[vacationData.Name] = [count, Math.max(mandatoryCount, 0)];
        return objForIE;
      });
      var vacationsAsString = vacations.map(function (vacation) {
        return Object.entries(vacation).map(function (vacationObj) {
          if (vacationObj[1][0] > -1){
            return '- ' + vacationObj[0] + ': ' + vacationObj[1][0] + ', ' + ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_MANDATORYDAYS') + ' ' + vacationObj[1][1];
          }
          else{
            return '- ' + vacationObj[0] + ': ' + ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_MANDATORYDAYS_EXCEEDED') + ' ' + Math.abs(vacationObj[1][0]);
          }
        });
      });
      functions.setValue('AvailableDays', vacationsAsString.join('<br/>'));
    }

    // Выполнение задания от совместителя
    ESS.network.sendRequest(`/api/functions/GetPerformerId?assignmentId=${functions.getValues().AssignmentId}`)
    .then(function (performerId) {
      functions.setValue('PerformerId', performerId);
      functions.setDataSource('AvailableVacationId', `/api/functions/GetAvailableVacationDays?userId=${performerId}`);
      ESS.network.sendRequest(`/api/functions/GetTableInstruction?assignmentId=${functions.getValues().AssignmentId}`)
      .then(function (instruction) {
        
        functions.setValue('Instruction', instruction.join('<br/>'));
        functions.setValue('IsShowWarningToast', false);

        ESS.network.sendRequest(`/api/functions/GetAvailableVacationDays?userId=${performerId}`)
        .then(function (availableDaysJson) {
          functions.setValue('AvailableDaysJson', JSON.stringify(availableDaysJson));
          var vacationsAsString = availableDaysJson.map(function (vacationData) {
            var vacationDuration = functions.getValues().VacationDuration
            if (vacationDuration !== null && vacationDuration < 0){
              return '- ' + vacationData.Name + ': ' + ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_MANDATORYDAYS_EXCEEDED') + ' ' + Math.abs(vacationData.Count - vacationDuration);
            }
            else{
              return '- ' + vacationData.Name + ': ' + vacationData.Count + ', ' + ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_MANDATORYDAYS') + ' ' + vacationData.MandatoryDays;
            }
          });
          functions.setValue('AvailableDays', vacationsAsString.join('<br/>'));
          var table = functions.getValues().PlannedVacationGrid;
          ESS.network.sendRequest(`/api/functions/GetSchedulingVacation?assignmentId=${functions.getValues().AssignmentId}`)
          .then(function (vacationsData) {
            var rows = functions.getValues().PlannedVacationGrid;
            var vacations = vacationsData.NewSchedulingVacationData;
            if (vacations.length > 0) {
              if (vacationsData.WarningText)
                ESS.toasts.showToast(vacationsData.WarningText, ESS.enums.ToastType.WARNING, false);
              for (var i = 0; i < vacations.length; i++) {
                var rowIndex = rows.length > i ? rows[i]['rowIndex'] : functions.addItem('PlannedVacationGrid');
                functions.setCellDataSource('PlannedVacationGrid', 
                  rowIndex, 
                  'AvailableVacationId', 
                  `/api/functions/GetAvailableVacationDays?userId=${performerId}`,
                  vacations[i]['VacationKindId']);
                functions.setValue('PlannedVacationGrid', vacations[i]['Begin'], rowIndex, 'BeginDate');
                functions.setValue('PlannedVacationGrid', vacations[i]['Duration'], rowIndex, 'VacationDuration');
                functions.setValue('PlannedVacationGrid', vacations[i]['End'], rowIndex, 'EndDate');
                functions.setValue('PlannedVacationGrid', i, rowIndex, 'VacationId');
              }
            }
            functions.setValue('IsShowWarningToast', true);

            ESS.network.sendRequest(`/api/functions/WarningDifferentVacationForScheduling?assignmentId=${functions.getValues().AssignmentId}`)
            .then(function (warning) {
              if(warning.length > 0) {
                ESS.toasts.showToast(warning, ESS.enums.ToastType.WARNING, false);
              }
            });

            resolve();
          })
          .catch(function (error) {
            ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
            reject();
          });
        })
        .catch(function (error) {
          ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
          reject();
        });
      })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
        reject();
      });
    })
    .catch(function (error) {
      ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
      reject();
    });
